alter table public.push_subscriptions enable row level security;
revoke all on public.push_subscriptions from public,anon,authenticated,service_role;
grant select,insert,update,delete on public.push_subscriptions to authenticated;
create policy push_subscriptions_select_own on public.push_subscriptions for select to authenticated using (user_id=auth.uid() and (select employee_hub_private.push_subscription_active_approved()));
create policy push_subscriptions_insert_own on public.push_subscriptions for insert to authenticated with check (user_id=auth.uid() and (select employee_hub_private.push_subscription_active_approved()));
create policy push_subscriptions_update_own on public.push_subscriptions for update to authenticated using (user_id=auth.uid() and (select employee_hub_private.push_subscription_active_approved())) with check (user_id=auth.uid() and (select employee_hub_private.push_subscription_active_approved()));
create policy push_subscriptions_delete_own on public.push_subscriptions for delete to authenticated using (user_id=auth.uid() and (select employee_hub_private.push_subscription_active_approved()));
create function employee_hub_private.guard_push_subscription_timestamps() returns trigger language plpgsql security definer set search_path='' as $$ begin if tg_op='INSERT' then new.created_at:=now();new.updated_at:=now();elsif new.created_at is distinct from old.created_at then raise exception 'created_at is immutable';else new.updated_at:=now();end if;return new;end $$;
revoke all on function employee_hub_private.guard_push_subscription_timestamps() from public,anon,authenticated,service_role;
create trigger guard_push_subscription_timestamps before insert or update on public.push_subscriptions for each row execute function employee_hub_private.guard_push_subscription_timestamps();
